        self.assert_code(
            base_request(measurements=missing), "invalid_capacity_measurement"
        )
        for bad in (0, -1.0, float("nan"), "x"):
            items = [
                {
                    "timestamp_s": 0,
                    "measured_capacity_ah": 100.0,
                    "cumulative_discharge_ah": 0.0,
                },
                {
                    "timestamp_s": 100,
                    "measured_capacity_ah": bad,
                    "cumulative_discharge_ah": 100.0,
                },
            ]
            self.assert_code(
